WITH c AS ( SELECT o.customer_id, COUNT(*) AS n FROM orders o WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2025-12-01' AND DATE '2025-12-31' GROUP BY 1) SELECT AVG(CASE WHEN n >= 2 THEN 1.0 ELSE 0.0 END) AS value FROM c
